01-javascript/10-temporal-dead-zone.starter:
function probeTdz() {
  // До объявления через var имя уже существует, через let — ещё нет.

  return {
    varBefore: null,
    letError: '',
    typeofVarBefore: '',
    typeofLetError: '',
    afterDeclaration: ''
  };
}

01-javascript/10-temporal-dead-zone.solution:
function probeTdz() {
  const varBefore = withVar;

  let letError = '';

  try {
    withLet;
  } catch (error) {
    letError = error.name;
  }

  const typeofVarBefore = typeof withVar;

  let typeofLetError = '';

  try {
    typeof withLet;
  } catch (error) {
    typeofLetError = error.name;
  }

  var withVar = 'объявлено';
  let withLet = 'объявлено';

  return {
    varBefore,
    letError,
    typeofVarBefore,
    typeofLetError,
    afterDeclaration: withLet
  };
}

01-javascript/11-primitive-types.starter:
function describeValue(value) {
  return '';
}

function tryMutate(value) {
  return { changed: false, result: undefined };
}

01-javascript/11-primitive-types.solution:
function describeValue(value) {
  if (value === null) {
    return 'null';
  }

  if (Array.isArray(value)) {
    return 'array';
  }

  return typeof value;
}

function tryMutate(value) {
  try {
    value.mutated = true;
  } catch {
    // Строгий режим запрещает присваивание свойства примитиву.
  }

  const result = value === null || value === undefined ? undefined : value.mutated;

  return { changed: result === true, result };
}

01-javascript/12-object-type.starter:
function applyOperations(target, operations) {
  return { reads: [], keys: [], missing: 0 };
}

tests.code:
const target = {};
const result = applyOperations(target, [
  { kind: 'set', key: 'id', value: 'WI-1' },
  { kind: 'read', key: 'id' }
]);
expect(result.reads).toEqual(['WI-1']);
expect(target.id).toBe('WI-1');

const target = { id: 'WI-1' };
const result = applyOperations(target, [{ kind: 'delete', key: 'id' }]);
expect(result.keys).toEqual([]);
expect('id' in target).toBe(false);

const result = applyOperations({}, [{ kind: 'read', key: 'нет' }]);
expect(result.reads).toEqual([undefined]);
expect(result.missing).toBe(1);

const result = applyOperations({}, [
  { kind: 'set', key: 'b', value: 2 },
  { kind: 'set', key: 'a', value: 1 }
]);
expect(result.keys).toEqual(['b', 'a']);

const result = applyOperations({ id: 'a' }, [{ kind: 'set', key: 'id', value: 'b' }]);
expect(result.keys).toEqual(['id']);
expect(result.missing).toBe(0);

let message = '';
try { applyOperations({}, [{ kind: 'обновить', key: 'id' }]); }
catch (error) { message = error.message; }
expect(message).toBe('неизвестная операция: обновить');

01-javascript/12-object-type.solution:
function applyOperations(target, operations) {
  const reads = [];
  let missing = 0;

  for (const operation of operations) {
    const exists = Object.hasOwn(target, operation.key);

    if (operation.kind === 'set') {
      target[operation.key] = operation.value;
      continue;
    }

    if (operation.kind === 'delete') {
      if (!exists) missing += 1;
      delete target[operation.key];
      continue;
    }

    if (operation.kind === 'read') {
      if (!exists) missing += 1;
      reads.push(target[operation.key]);
      continue;
    }

    throw new Error('неизвестная операция: ' + operation.kind);
  }

  return { reads, keys: Object.keys(target), missing };
}

01-javascript/13-references.starter:
function share(source) {
  return { same: source, copy: source };
}

function mutate(target) {
  return target;
}

function compare(a, b) {
  return { byReference: false, byContent: false };
}

tests.code:
const source = { visits: 1 };
const { same, copy } = share(source);
expect(same === source).toBe(true);
expect(copy === source).toBe(false);

const source = { visits: 1 };
const { same } = share(source);
mutate(same);
expect(source.visits).toBe(2);

const source = { visits: 1 };
const { copy } = share(source);
mutate(copy);
expect(source.visits).toBe(1);
expect(copy.visits).toBe(2);

const first = { id: 'a' };
const second = { id: 'a' };
expect(compare(first, second)).toEqual({ byReference: false, byContent: true });
expect(compare(first, first)).toEqual({ byReference: true, byContent: true });

const nested = { count: 0 };
const source = { nested };
const { copy } = share(source);
copy.nested.count = 5;
expect(nested.count).toBe(5);

01-javascript/13-references.solution:
function share(source) {
  return { same: source, copy: { ...source } };
}

function mutate(target) {
  target.visits = (target.visits ?? 0) + 1;

  return target;
}

function compare(a, b) {
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);

  const byContent = keysA.length === keysB.length
    && keysA.every(key => a[key] === b[key]);

  return { byReference: a === b, byContent };
}

