01-javascript/15-type-conversion.solution:
function parseRetries(raw) {
  if (typeof raw !== 'string' || raw.trim() === '') {
    return 0;
  }

  const parsed = Number(raw);

  return Number.isFinite(parsed) ? parsed : 0;
}

