01-javascript/24-parameters.solution:
function buildUrl(path, baseUrl = 'http://127.0.0.1:4310', query = {}) {
  const pairs = Object.entries(query).map(([key, value]) => key + '=' + value);

  return pairs.length === 0
    ? baseUrl + path
    : baseUrl + path + '?' + pairs.join('&');
}

