function* idSequence(prefix) {
  let number = 1;

  while (true) {
    yield prefix + '-' + number;
    number += 1;
  }
}

function takeIds(generator, count) {
  const values = [];

  for (let index = 0; index < count; index += 1) {
    values.push(generator.next().value);
  }

  return values;
}

