01-javascript/83-generators.solution:
function* steps() {
  yield 'first';
  yield 'second';

  return 'done';
}

function collectBySpread() {
  return [...steps()];
}

function collectByNext() {
  const generator = steps();
  const values = [];

  while (true) {
    const step = generator.next();
    values.push(step.value);

    if (step.done) {
      return values;
    }
  }
}

