01-javascript/84-custom-iteration.solution:
function createSuite(name) {
  const tests = [];

  return {
    name,

    add(title, status) {
      tests.push({ title, status });
    },

    size() {
      return tests.length;
    },

    failed() {
      return {
        *[Symbol.iterator]() {
          for (const test of tests) {
            if (test.status === 'failed') {
              yield test;
            }
          }
        }
      };
    },

    *[Symbol.iterator]() {
      for (const test of tests) {
        yield test;
      }
    }
  };
}

01-javascript/89-performance.starter:
function memoize(fn) {
  const wrapped = argument => fn(argument);

  wrapped.calls = 0;
  wrapped.hits = 0;

  return wrapped;
}

tests.code:
let calls = 0;
const slow = value => { calls += 1; return value * 2; };
const fast = memoize(slow);
expect(fast(2)).toBe(4);
expect(fast(2)).toBe(4);
expect(calls).toBe(1);

const fast = memoize(value => value);
fast('a');
fast('a');
fast('b');
expect(fast.calls).toBe(2);
expect(fast.hits).toBe(1);

let calls = 0;
const fast = memoize(value => { calls += 1; return value; });
fast(1);
fast(2);
expect(calls).toBe(2);

let calls = 0;
const fast = memoize(() => { calls += 1; return undefined; });
expect(fast('x')).toBeUndefined();
expect(fast('x')).toBeUndefined();
expect(calls).toBe(1);

let attempts = 0;
const flaky = memoize(() => {
  attempts += 1;
  if (attempts === 1) throw new Error('временный сбой');
  return 'готово';
});
let failed = false;
try { flaky('x'); } catch { failed = true; }
expect(failed).toBe(true);
expect(flaky('x')).toBe('готово');
expect(attempts).toBe(2);

const first = memoize(value => value);
const second = memoize(value => value);
first('a');
expect(second.calls).toBe(0);

01-javascript/89-performance.solution:
function memoize(fn) {
  const cache = new Map();

  const wrapped = argument => {
    if (cache.has(argument)) {
      wrapped.hits += 1;

      return cache.get(argument);
    }

    // Счётчик увеличивается до вызова: упавший вызов тоже был вызовом.
    wrapped.calls += 1;

    const result = fn(argument);

    cache.set(argument, result);

    return result;
  };

  wrapped.calls = 0;
  wrapped.hits = 0;

  return wrapped;
}

