01-javascript/94-json.solution:
function safeStringify(value) {
  const seen = new Set();

  try {
    return JSON.stringify(value, (key, current) => {
      if (typeof current === 'object' && current !== null) {
        if (seen.has(current)) {
          return '[circular]';
        }

        seen.add(current);
      }

      return current;
    });
  } catch (error) {
    return null;
  }
}

