02-typescript/105-void-and-never.solution:
function forEachStep(steps: string[], action: (step: string) => void): number {
  let calls = 0;

  for (const step of steps) {
    action(step);
    calls += 1;
  }

  return calls;
}

function fail(message: string): never {
  throw new Error(message);
}

function runSafely(steps: string[], action: (step: string) => void) {
  let calls = 0;

  try {
    forEachStep(steps, step => {
      action(step);
      calls += 1;
    });

    return { calls, failedAt: null as string | null };
  } catch (error) {
    return { calls, failedAt: (error as Error).message };
  }
}

