  if (Array.isArray(value)) return 'array';
  if (value instanceof Date) return 'date';

  const kind = typeof value;

  if (kind === 'number') {
    return Number.isNaN(value) ? 'other' : 'number';
  }

  if (kind === 'object' || kind === 'string' || kind === 'boolean'
    || kind === 'function' || kind === 'undefined') {
    return kind;
  }

  return 'other';
}

