type Status = 'passed' | 'failed' | 'skipped';

function weight(status: Status): number {
  switch (status) {
    case 'passed':
      return 0;
    case 'failed':
      return 1;
    case 'skipped':
      return 2;
    default: {
      const unknownStatus: never = status;

      throw new Error('неизвестный статус: ' + String(unknownStatus));
    }
  }
}

