03-automation-qa/174-hooks-and-test-life.solution:
async function runSuite(suite) {
  const log = [];
  const results = [];

  const callHook = async name => {
    const hook = suite[name];

    if (hook === undefined) return true;

    log.push(name);

    try {
      await hook();

      return true;
    } catch {
      return false;
    }
  };

  const prepared = await callHook('beforeAll');

  if (prepared) {
    for (const test of suite.tests) {
      let status = 'passed';

      try {
        const ready = await callHook('beforeEach');

        if (!ready) {
          status = 'failed';
        } else {
          log.push(test.name);
          await test.fn();
        }
      } catch {
        status = 'failed';
      } finally {
        await callHook('afterEach');
      }

      results.push({ name: test.name, status });
    }
  }

  await callHook('afterAll');

  return { results, log };
}

