async function runWithRetry(action, options) {
  const { attempts, isRetriable } = options;
  let made = 0;

  while (true) {
    made += 1;

    try {
      return { value: await action(), attempts: made };
    } catch (error) {
      const canRetry = isRetriable(error) && made < attempts;

      if (!canRetry) {
        error.attempts = made;
        throw error;
      }
    }
  }
}

